from collections import deque

def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    k = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}
    transitions = [[-1] * k]
    failure = [0]
    bad = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * k)
                failure.append(0)
                bad.append(False)
            state = transitions[state][c]
        bad[state] = True

    queue = deque()
    for c in range(k):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        fallback = failure[state]
        bad[state] |= bad[fallback]
        for c in range(k):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[fallback][c]
            else:
                failure[child] = transitions[fallback][c]
                queue.append(child)

    safe_states = [s for s in range(len(transitions)) if not bad[s]]
    index = {s: i for i, s in enumerate(safe_states)}
    size = len(safe_states)
    matrix = [[0] * size for _ in range(size)]

    for state in safe_states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not bad[target]:
                row[index[target]] += 1

    def multiply(a, b):
        result = [[0] * size for _ in range(size)]
        for i, a_row in enumerate(a):
            row = result[i]
            for j, coefficient in enumerate(a_row):
                if coefficient:
                    for t, value in enumerate(b[j]):
                        if value:
                            row[t] += coefficient * value
            for t in range(size):
                row[t] %= MOD
        return result

    counts = [0] * size
    counts[index[0]] = 1

    while n:
        if n & 1:
            updated = [0] * size
            for i, count in enumerate(counts):
                if count:
                    for j, value in enumerate(matrix[i]):
                        updated[j] += count * value
            counts = [value % MOD for value in updated]
        n >>= 1
        if n:
            matrix = multiply(matrix, matrix)

    return sum(counts) % MOD
